valid_parentheses.brute:
changed = true
while changed:   (rescan from the start after each deletion)
    changed = false
    for each pair in "()", "[]", "{}":
        if pair appears in s:
            delete its first occurrence from s
            changed = true
return s is empty

valid_parentheses.optimal:
pairs = dict closer -> the opener it needs
stack = empty
for each ch in s:
    if ch is a closer:
        if the stack is empty: return false
        top = pop the stack
        if top != pairs[ch]: return false   (the closer must match the innermost opener)
    else:
        push ch
return the stack is empty   (leftover openers mean invalid)

evaluate_reverse_polish_notation.brute:
tokens = copy of tokens
while more than one token remains:   (one reduction per full rescan)
    for each index i:
        if tokens[i] is an operator:
            a = tokens[i - 2] as a number, b = tokens[i - 1] as a number
            value = a op b   (division truncates toward zero)
            tokens = tokens before i - 2 + [value] + tokens after i
            break
return the single remaining token as a number

evaluate_reverse_polish_notation.optimal:
stack = empty
for each token:
    if token is an operator:
        b = pop the top   (popped first, but it is the RIGHT operand)
        a = pop the top
        push a op b   (division truncates toward zero)
    else:
        push token as a number
return the only element on the stack

decode_string.optimal:
stack = empty stack of frames [text before the "[", repeat count]
current = "", num = 0
for each ch in s:
    if ch is a digit: num = num * 10 + ch   (counts can have several digits)
    else if ch == "[":
        push [current, num]   (park the outer text and its count)
        current = "", num = 0
    else if ch == "]":
        frame = pop the top
        current = frame's text + current repeated frame's count times   (resume the outer text)
    else: append ch to current
return current

basic_calculator_ii.brute:
tokens = tokenize(s)   (numbers and operators alternate, spaces dropped)
for each level in ("*/", "+-"):   (two passes: high precedence first)
    i = 1   (operators sit at the odd positions)
    while i < size of tokens:
        if tokens[i] is in level:
            value = tokens[i - 1] op tokens[i + 1]
            tokens = tokens before i - 1 + [value] + tokens after i + 1   (splice shifts the tail)
        else: i += 2
return tokens[0]

daily_temperatures.brute:
answer = array of n zeros
for each day i:
    for each later day j > i:   (walks over cooler days that are also waiting)
        if temperatures[j] > temperatures[i]:
            answer[i] = j - i
            break
return answer

car_fleet.brute:
fleets = 0
for each car i:
    time_i = (target - position[i]) / speed[i]
    leader = true
    for each car j:   (rescans every car ahead of i)
        if position[j] > position[i]:
            time_j = (target - position[j]) / speed[j]
            if time_j >= time_i: leader = false   (i catches car j, so it joins a fleet)
    if leader: fleets += 1
return fleets

dota2_senate.brute:
n = length of senate, banned = n falses
loop forever:
    for each i from 0 to n - 1:
        if banned[i]: continue
        j = (i + 1) mod n
        while j != i and (banned[j] or senate[j] == senate[i]): j = (j + 1) mod n   (scan for an opponent)
        if j == i:   (no opponent left: senator i's party wins)
            return "Radiant" if senate[i] == "R" else "Dire"
        banned[j] = true
